/**
 * The building blocks of a contract check: the generated OpenAPI schemas and the two assertions that
 * hold hand-written API types to them. The kernel's check is `contract.check.ts`; each module has its
 * own for its API slice (`src/modules/<id>/api/contract.check.ts`). Types only: no runtime cost.
 */

import type { components } from './schema.gen';

/** The schemas of docs/openapi.json (generated by `npm run gen:api`). */
export type Schemas = components['schemas'];

/**
 * A response as it is on the wire: FastAPI serialises every field of a response model, defaults
 * included, so a field the schema marks optional (it has a default) is always present.
 */
export type Wire<T> = T extends readonly (infer U)[] ? Wire<U>[] : T extends object ? { [K in keyof T]-?: Wire<Exclude<T[K], undefined>> } : T;

/** Fails to compile unless `Generated` (the API's response) is assignable to `Hand`. */
export type Response<Generated extends Hand, Hand> = [Generated, Hand];

/** Fails to compile unless `Hand` (the body the app sends) is assignable to `Generated`. */
export type Request<Hand extends Generated, Generated> = [Hand, Generated];
